from pathlib import Path
from playwright.sync_api import sync_playwright
import json,traceback
root=Path(__file__).parent.parent
import http.server, threading, functools
class QuietHandler(http.server.SimpleHTTPRequestHandler):
 def log_message(self, format, *args): pass
server=http.server.ThreadingHTTPServer(('127.0.0.1',0),functools.partial(QuietHandler,directory=str(root)))
threading.Thread(target=server.serve_forever,daemon=True).start()
BASE='http://127.0.0.1:'+str(server.server_address[1])
checks=[];errors=[]
def ok(name,test):
 assert test,name
 checks.append({'name':name,'status':'passed'})
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox'],env={'XDG_CONFIG_HOME':'/tmp/thesis-pw-config','XDG_CACHE_HOME':'/tmp/thesis-pw-cache'})
 ctx=browser.new_context(viewport={'width':1440,'height':1000},accept_downloads=True)
 page=ctx.new_page();page.on('pageerror',lambda e:errors.append(str(e)))
 page.goto(BASE+'/可点击原型.html');page.wait_for_selector('h1')
 page.evaluate('S=seed();save();render()');ok('初始11页导航',page.locator('#nav button').count()==11)
 page.screenshot(path=str(root/'原型首页.png'),full_page=True)
 page.evaluate("go('board')");page.get_by_role('button',name='推进一阶段（模拟） →').click();ok('未确认方案禁止制作',page.evaluate('P().phase===0&&P().approved===0'))
 page.evaluate("go('plan')");page.get_by_role('button',name='确认演示方案并执行 →').click();ok('四区方案确认开启派发',page.evaluate("P().status==='running'&&P().approved===P().plan"))
 page.get_by_role('button',name='推进一阶段（模拟） →').click();ok('检查点阶段推进',page.evaluate('P().phase===1'))
 page.get_by_role('button',name='注入业务失败',exact=True).click();ok('业务失败转人工',page.evaluate("P().status==='failed_waiting_user'&&P().failed"))
 page.evaluate("go('board')");page.get_by_role('button',name='推进一阶段（模拟） →').click();ok('失败后禁止自主推进',page.evaluate('P().phase===1'))
 page.evaluate("go('recovery')");b=page.evaluate("S.projects[1].progress");page.get_by_role('button',name='推进另一个项目（模拟）').click();ok('A失败B继续',page.evaluate("S.projects[1].progress")>b and page.evaluate('P().failed'))
 page.get_by_role('button',name='人工处理后恢复此节点').click();ok('无人工记录不恢复',page.evaluate('P().failed'))
 page.get_by_label('人工恢复处理记录').fill('已补充附录并重新核验');page.get_by_role('button',name='人工处理后恢复此节点').click();ok('人工恢复保留检查点',page.evaluate("!P().failed&&P().phase===1&&P().status==='running'"))
 page.get_by_role('button',name='模拟 429 → 切换成功').click();ok('API有限切换保持业务状态',page.evaluate("P().status==='running'&&S.apiEvents[0].includes('提交一次')"))
 page.get_by_role('button',name='模拟全部渠道失败').click();ok('API耗尽转人工',page.evaluate("P().failed&&P().status==='failed_waiting_user'"))
 page.get_by_label('人工恢复处理记录').fill('渠道配置已修复');page.get_by_role('button',name='人工处理后恢复此节点').click()
 page.evaluate("go('crew')");ok('96个岗位目录',page.locator('.agentcard').count()==96)
 page.get_by_role('button',name='召开双轮方案讨论').click();page.get_by_role('button',name='将讨论结论写入本项目决策板').click();ok('会议结果进决策不自动批准',page.evaluate("P().decisions[0].status==='待决策'"))
 page.evaluate("go('crew');roleDetail('R011')");page.get_by_role('button',name='运行演示自测并加入本项目').click();ok('岗位模拟招募实例',page.evaluate("P().extraRoles.includes('R011')"))
 page.evaluate("go('board')")
 for _ in range(3):page.get_by_role('button',name='推进一阶段（模拟） →').click()
 ok('检查通过仅待用户验收',page.evaluate("P().status==='awaiting_acceptance'&&!P().accepted&&P().phase===4"))
 page.evaluate("go('artifacts')");ok('外文与开题共6格式槽位',page.locator('.filecard').count()==6)
 page.screenshot(path=str(root/'原型成果验收.png'),full_page=True)
 page.get_by_role('button',name='确认验收本版本').click();ok('用户验收后才完成',page.evaluate("P().status==='completed'&&P().accepted"))
 page.get_by_label('成果修改意见').fill('统一译文术语');page.get_by_role('button',name='保存修改意见并建修订任务').click();ok('修改建修订任务不沿用完成',page.evaluate("P().status==='running'&&!P().accepted&&P().comments.length===1"))
 page.evaluate("go('plan')");page.get_by_role('button',name='修改方案版本').click();page.locator('#planReason').fill('更换外文候选');page.get_by_role('button',name='保存新版本').click();ok('实质变更冻结新版本并关制作门',page.evaluate("P().plan===2&&P().approved===0&&P().status==='awaiting_plan_approval'"))
 page.evaluate("go('resources')");page.get_by_label('搜索资源').fill('octopus');page.get_by_label('搜索资源').press('Tab');ok('开源资源可检索具体组合',page.locator('tbody tr').count()>0 and 'octopus' in page.locator('tbody').inner_text().lower())
 page.evaluate("S.resourceQuery='';S.resourceMode='all';S.resourcePage=0;render()");ok('全量884索引分页',page.locator('tbody tr').count()==20 and '884' in page.locator('#content').inner_text())
 page.evaluate("go('board');S.branch='PLC';render()");ok('专业分支可切换',page.locator('#content').inner_text().find('PLC-01')>=0)
 page.evaluate("go('overview')");page.get_by_role('button',name='＋ 新建项目').click();page.locator('#newName').fill('<测试> 跨专业项目');page.get_by_role('button',name='创建演示项目').click();ok('新项目隔离并转义用户输入',page.evaluate("S.projects.length===4&&P().name==='<测试> 跨专业项目'"))
 page.reload();ok('刷新恢复本地项目状态',page.evaluate("S.projects.length===4&&P().name==='<测试> 跨专业项目'"))
 page.get_by_role('button',name='评估方案 ↗').click();page.evaluate("rate('多Agent协作',4)");page.locator('#evaluationNote').fill('需要增加专业软件占用视图')
 with page.expect_download() as d:page.get_by_role('button',name='下载评估JSON').click()
 download=d.value;download.save_as(str(root/'research/evaluation-test.json'));ok('评估可导出',json.loads((root/'research/evaluation-test.json').read_text())['reviews']['多Agent协作']==4)
 page.evaluate('closeModal();S=seed();save();render()')
 for id in ['overview','workspace','plan','crew','board','decisions','evidence','artifacts','resources','recovery','architecture']:
  page.evaluate(f"go('{id}')");ok('页面无横向溢出 '+id,page.evaluate('document.documentElement.scrollWidth<=window.innerWidth+1'))
 page.evaluate("go('crew')");page.screenshot(path=str(root/'原型团队岗位.png'),full_page=False)
 page.evaluate("go('workspace')");page.screenshot(path=str(root/'原型项目工作区.png'),full_page=True)
 page.set_viewport_size({'width':768,'height':1000});page.evaluate("go('overview')");ok('768px响应式无页面溢出',page.evaluate('document.documentElement.scrollWidth<=window.innerWidth+1'))
 page.set_viewport_size({'width':390,'height':844});page.evaluate("go('plan')");ok('390px方案确认无页面溢出',page.evaluate('document.documentElement.scrollWidth<=window.innerWidth+1'))
 page.screenshot(path=str(root/'research/mobile-plan.png'),full_page=True)
 page.set_viewport_size({'width':1440,'height':1000});page.goto(BASE+'/架构图.html');page.wait_for_timeout(1200)
 ok('Archify生成图HTTP真实浏览器可打开',page.locator('svg').count()>0)
 ok('架构图无横向溢出',page.evaluate('document.documentElement.scrollWidth<=window.innerWidth+1'))
 page.screenshot(path=str(root/'架构图预览.png'),full_page=True)
 svgs=page.locator('svg').all();big=max(svgs,key=lambda x:len(x.evaluate('(x)=>x.outerHTML')));(root/'架构图.svg').write_text(big.evaluate('(x)=>x.outerHTML'))
 page.pdf(path=str(root/'架构图.pdf'),format='A3',print_background=True,landscape=True)
 ok('无JavaScript异常',len(errors)==0)
 browser.close()
(root/'research/prototype-test-report.json').write_text(json.dumps({'passed':len(checks),'failed':0,'checks':checks,'js_errors':errors,'note':'浏览器验证原型模拟行为；不等同真实Agent、论文或网关端到端验证。Archify自带file导航browser-check受当前浏览器策略限制，改用HTTP独立验证。'},ensure_ascii=False,indent=2))
print('PASSED',len(checks),'JS_ERRORS',errors)
